  pageId: 1,
  function: `() => {
    const out = {};
    out.title = document.title;
    // eBay header search box variations
    const ids = ['gh-tb','gh-tw','gh-searchbox','sb','search'];
    const byId = [];
    for (const id of ids) { const el = document.getElementById(id); if (el) byId.push({id, name: el.getAttribute('name'), placeholder: el.placeholder || ''}); }
    out.searchById = byId;
    // all text inputs in header
    const header = document.querySelector('#gh-header') || document.querySelector('header') || document.querySelector('[class*="header"]');
    out.headerCount = header ? header.querySelectorAll('input[type=text], input:not([type]), textarea').length : null;
    // count links to detect loaded nav
    out.bodyLen = document.body ? document.body.innerText.length : 0;
    return out;
  }`,
});
console.log(JSON.stringify(info, null, 2));

