await tools.cdt.evaluate_script({
  pageId: 1,
  function: `() => {
    const results = [];
    document.querySelectorAll('input').forEach(el => {
      if (el.type !== 'hidden') {
        results.push({
          id: el.id, name: el.getAttribute('name'), type: el.type,
          placeholder: el.placeholder, ariaLabel: el.getAttribute('aria-label'),
          role: el.getAttribute('role'), testid: el.getAttribute('data-testid') || el.getAttribute('testid') || '',
        });
      }
    });
    // find search button(s)
    const buttons = [];
    document.querySelectorAll('button').forEach(el => {
      buttons.push({ id: el.id, ariaLabel: el.getAttribute('aria-label'), text: el.innerText?.slice(0,30), testid: el.getAttribute('data-testid') || '' });
    });
    return { inputs: results, buttonCount: buttons.length, sampleButtons: buttons.slice(0,5) };
  }`,
});

