await tools.cdt.evaluate_script({
  pageId: 1,
  function: `() => {
    var out = {};
    // results container candidates
    ['srp-results','results','srp-ResultsGrid','main.results'].forEach(function(id){
      var el = document.getElementById(id);
      if (el) out['id_'+id] = el.tagName + '.' + String(el.className).slice(0,80);
    });
    var grid = document.querySelector('[id^=srp-], [class*=results-grid], .srp-results');
    // About the listing tiles count (eBay tile label)
    out['aboutListing'] = document.querySelectorAll('[aria-label^=About the listing]').length;
    out['sitem'] = document.querySelectorAll('.srp-item').length;
    out['ul>li with resultsAttr'] = document.querySelectorAll('ul[data-attribute] li').length;
    // Look for elements whose text contains a price and shipping
    var tiles = [];
    var all = document.querySelectorAll('*');
    for (var i=0;i<all.length;i++){
      var t = all[i].getAttribute && all[i].getAttribute('aria-label') || '';
      if (typeof t === 'string' && t.indexOf('About the listing') === 0) tiles.push(t.slice(0,80));
    }
    out['tileLabelsSample'] = tiles.slice(0,3);
    // fallback: find the element that has many <a> with /itm/ 
    var itmLinks = document.querySelectorAll('a[href*=\/itm\\/]').length;
    out['itmLinkCount'] = itmLinks;
    return out;
  }`,
});

