  function: `() => {
    var anchors = document.querySelectorAll('a[href*="/itm/"]');
    var first = anchors[0];
    // walk up to find a tile root and capture chain of tag+class
    var chain = [];
    var el = first;
    for (var level = 0; level < 12 && el; level++){
      var comp = el.getAttribute && el.getAttribute('data-component');
      chain.push(el.tagName + (el.id ? '#' + el.id : '') + '.' + String(el.className).slice(0,50) + (comp ? ' [dc=' + comp + ']' : ''));
      el = el.parentElement;
    }
    var shadowAncestors = [];
    el = first;
    for (var j = 0; j < 8 && el; j++){
      if (el.shadowRoot) shadowAncestors.push(el.tagName + (el.id || ''));
      el = el.parentElement;
    }
    var allShadowRoots = 0;
    function countSR(node){ if (!node) return; if (node.shadowRoot) allShadowRoots++; Array.prototype.forEach.call(node.children||[], function(c){ countSR(c); }); }
    // also count elements with role=grid/listitem anywhere including nested shadow via a simpler heuristic: custom elements
    var customEls = document.getElementsByTagName('*');
    var customCount = 0; var sample = [];
    for (var k = 0; k < customEls.length; k++){
