  pageId: 1,
  function: `() => {
    var cards = document.querySelectorAll('li.s-card--horizontal');
    function txt(sel){ var e = cards[0] && cards[0].querySelector(sel); return e ? (e.innerText||'').trim() : ''; }
    function extract(card){
      // title link is the one inside su-card-container__content
      var contentCard = card.querySelector('.su-card-container__content');
