        ariaTitle: titleLink ? (titleLink.getAttribute('aria-label')||'').trim() : '',
        price: priceEl ? (priceEl.innerText||'').trim() : '',
        subtitles: subtitleEls,
        url: titleLink ? ((titleLink.getAttribute('href')||'').trim()) : ''
      };
    }
    var out = [];
    for (var i = 0; i < cards.length && i < 16; i++){
