await tools.cdt.evaluate_script({
  pageId: 1,
  function: `() => {
    function num(s){ if(!s) return null; var m = s.match(/\\$?([0-9,]+\\.?[0-9]*)/); if(!m) return null; return parseFloat(m[1].replace(/,/g,'')); }
    var cards = document.querySelectorAll('li.s-card--horizontal');
    function extract(card){
      var content = card.querySelector('.su-card-container__content');
      var titleLink = content ? content.querySelector('a.s-card__link') : null;
      var subtitles = Array.prototype.map.call(content ? content.querySelectorAll('.s-card__subtitle') : [], function(s){ return (s.innerText||'').trim(); });
      // shipping: any subtitle/footer containing 'ship'
      var allText = [];
      var subs = content ? content.querySelectorAll('.s-card__subtitle, .s-card__footer, [class*=shipping], [class*=Ship]') : [];
      subs.forEach(function(s){ if(/shipp/i.test(s.innerText||'') || /ship/i.test((s.className||''))) allText.push((s.innerText||'').trim()); });
      var priceEl = card.querySelector('.s-card__price');
      return {
        title: titleLink ? (titleLink.innerText.replace(/\s+/g,' ').trim()) : '',
        priceTxt: priceEl ? (priceEl.innerText.trim()) : '',
        price: num(priceEl ? priceEl.innerText : ''),
        subs: subtitles,
        shipText: allText.slice(0,4),
        url: titleLink ? (titleLink.getAttribute('href')||'').trim() : ''
      };
    }
    var out = [];
    cards.forEach(function(c){ out.push(extract(c)); });
    // filter to relevant XM6 headphones: contains 'XM6', not XM5/XM4, not accessory words alone
    function relevant(x){
      if(!/XM6/i.test(x.title)) return false;
      var t = x.title.replace(/,/g,' ');
      if(/XM5|XM4|XM3|XM2|XM1/i.test(t)) return false;
      // skip accessory-only titles (but allow if XM6 present)
      var acc = /case|pad|cable|charger|adapter|clip|band|earbud|earpad|headband|microphone|^wire$|only/i.test(t);
      if(acc && !/XM6|XM-6/i.test(t.replace(/Case|Headphones/g,''))) {} // keep as is
      return true;
    }
    var rel = out.filter(relevant);
    rel.sort(function(a,b){ return (a.price==null?1e9:a.price) - (b.price==null?1e9:b.price); });
    return { totalCards: cards.length, relevantCount: rel.length, sortedRel: rel.slice(0,12), sampleFull: out.slice(0,3) };
  }`,
});

