  pageId: 1,
  waitForStableDom: true,
  function: `async () => {
    var sleep = ms=>new Promise(r=>setTimeout(r,ms));
    var seenCards = new Set();
    var all = [];
    function extract(){
      var cards = document.querySelectorAll('li.s-card--horizontal');
      // dedupe by listingid or position; we'll rebuild each pass to capture lazy-loaded ones
      return cards;
    }
    async function collectAll(){
      var stable=0; lastId='';
      for (var pass=0; pass<25 && stable<4; pass++){
        window.scrollBy({top: 1600, behavior:'auto'});
        await sleep(700);
        // also scroll near bottom to trigger far tiles
        var arr = Array.prototype.slice.call(document.querySelectorAll('li.s-card--horizontal'));
        var key = arr.length + '|' + (arr[arr.length-1]?.getAttribute('data-listingid')||'');
        if(key===lastId) stable++; else {stable=0; lastId=key;}
        all = arr.slice();
      }
      // final scroll to top
      window.scrollTo({top:0, behavior:'auto'});
      await sleep(500);
    }
    async function parse(cards){
      function num(s){var m=s.match(/\\$?([0-9,]+\\.?[0-9]*)/);return m?parseFloat(m[1].replace(/,/g,'')):null;}
      function clean(t){return t.replace(/\\s+/g,' ').trim();}
      var out=[];
      cards.forEach(function(c){
        var content=c.querySelector('.su-card-container__content');
        var titleLink=content?content.querySelector('a.s-card__link'):null;
        var titleEl=content?content.querySelector('.s-card__title'):null;
        var title=titleEl?clean(titleEl.innerText):(titleLink?clean(titleLink.innerText):'');
        var subs=[]; if(content) content.querySelectorAll('.s-card__subtitle').forEach(function(el){var t=clean(el.innerText);if(t)subs.push(t);});
        var shipLines=[]; if(content) content.querySelectorAll('.s-card__subtitle,.s-card__footer').forEach(function(el){if(/shipp/i.test(el.innerText))shipLines.push(clean(el.innerText));});
        var p=num((content.querySelector('.s-card__price')||{}).innerText||'');
        out.push({title:title, price:p, priceTxt:clean((content.querySelector('.s-card__price')||{}).innerText), subs:subs, shipping:shipLines, url:(titleLink&&titleLink.getAttribute('href'))||''});
      });
      return out;
    }
    await collectAll();
    var cards = Array.prototype.slice.call(document.querySelectorAll('li.s-card--horizontal'));
    var parsed = await parse(cards);
    function bucket(x){var t=x.subs.join(' | '); if(/refurbish/i.test(t))return 'Refurbished'; if(/brand new/i.test(t))return 'Brand New'; if(/open box/i.test(t))return 'Open Box'; return 'Other:'+t;}
    var dist={}; parsed.forEach(function(p){dist[bucket(p)]=(dist[bucket(p)]||0)+1;});
    function relevant(x){var t=x.title.replace(/,/g,' '); return /XM6/i.test(t) && !/XM5|XM4|XM3|XM2|XM1/i.test(t);}
    var rel = parsed.filter(relevant);
    // keep only refurb for the "refurbished" answer
    var relRefurb = rel.filter(function(x){return /refurbish/i.test(x.subs.join(' '));});
