    var rel = parsed.filter(relevant);
    // keep only refurb for the "refurbished" answer
    var relRefurb = rel.filter(function(x){return /refurbish/i.test(x.subs.join(' '));});
    rel.sort(function(a,b){return (a.price==null?1e9:a.price)-(b.price==null?1e9:b.price);});
    relRefurb.sort(function(a,b){return (a.price==null?1e9:a.price)-(b.price==null?1e9:b.price);});
    return { totalLoaded: cards.length, buckets: dist, totalCountRel: rel.length, refurbCount: relRefurb.length, cheapestRelAll: rel.slice(0,8), cheapestRelRefurb: relRefurb.slice(0,8) };
  }

