await tools.cdt.evaluate_script({
  pageId: 1,
  function: `() => {
    // locate "Condition" DisclosureTriangle
    var all = document.getElementsByTagName('*');
    var condHeaders = [];
    for (var i=0;i<all.length;i++){
      var el = all[i];
      if((el.getAttribute('role')==='disclosuretriangle' || el.classList.contains('DisclosureTriangle')) && /Condition/.test(el.innerText||'')) condHeaders.push(el);
    }
    var res = [];
    condHeaders.forEach(function(h){
      var expanded = h.getAttribute('aria-expanded');
      // panel is usually next siblings or child container
      var panel = h.parentElement ? h.parentElement.querySelector('[role=group], [role=tree], .filter-tile, ul, ol') : null;
      // collect toggle elements within panel (or whole header subtree)
      var scope = panel || h;
      var toggles = [];
      scope.querySelectorAll('li, button, span[role], a, div[role="checkbox"], div[role="button"]').forEach(function(t){
        if(t.closest('[role=tree]') && t.getAttribute('data-id')){ /* maybe */ }
        var txt = (t.innerText||'').trim();
        if(txt && /New|Used|Pre-Owned|Refurbished|Open Box|Excellent|Good|Very Good|Certified/Premium/i.test(txt)) toggles.push({txt: txt.slice(0,40), role:t.getAttribute('role'), pressed:t.getAttribute('aria-pressed'), checked:t.getAttribute('aria-checked'), id:t.getAttribute('data-id'), class:String(t.className).slice(0,60)});
      });
      res.push({ expanded: expanded, panelFound: !!panel, toggleCount: toggles.length, sampleToggles: toggles.slice(0,12) });
    });
    return res;
  }`,
});

