const data = await tools.cdt.evaluate_script({
  pageId: 1,
  script: `(ctx) => {
    // Scroll to bottom to load more tiles
    const doScroll = async () => {
      const scrollSteps = [];
      for (let i = 0; i < 8; i++) {
        window.scrollTo(0, document.body.scrollHeight);
        await new Promise(r => setTimeout(r, 350));
        scrollSteps.push(document.querySelectorAll('.s-card').length);
      }
    };
    // Single pass scroll (not awaited inside) - do it synchronously below
    return { totalCards: document.querySelectorAll('.s-card').length };
  }
});
return JSON.stringify(data);

